INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('defence-exports','Defence exports','Value of defence goods and services exported from India, as reported by the Ministry of Defence. Counts authorisations realised, not order book.','defence','₹ crore (nominal)','₹ cr','fiscal-year',true,'official','high','2026-08-17',ARRAY['Nominal rupees, not inflation-adjusted. Roughly a third of the 2013-14 to 2025-26 growth is rupee inflation and depreciation.','FY2014-15 and FY2015-16 are omitted rather than estimated: no primary release was located for those two years at the time of verification.','The FY2018-19 spike and FY2019-20 fall largely reflect a small number of large contracts, not a trend reversal.']::text[],ARRAY['pib-defexp-fy25','pib-defexp-fy24','vif-defence-exports','theprint-defexp-fy25']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('defence-production','Defence production','Total value of defence items produced in India by DPSUs, other PSUs and private firms in a fiscal year.','defence','₹ crore (nominal)','₹ cr','fiscal-year',true,'official','medium','2026-08-17',ARRAY['FY2024-25 was first announced as ₹1,50,590 crore and later restated to ~₹1.54 lakh crore once remaining private-sector returns were counted. The revised figure is shown and flagged.','Production value counts output, not indigenous content. A platform assembled here from imported kits counts in full — this series is not a measure of self-reliance on its own.']::text[],ARRAY['pib-defprod-fy25','pib-defence-decade']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('defence-production-private-share','Private sector share of defence production','Share of total defence production value contributed by private firms rather than DPSUs and other public undertakings.','defence','% of production value','%','fiscal-year',NULL,'official','medium','2026-08-17',ARRAY['Direction of ''good'' is genuinely contested: a higher private share signals a broader industrial base, but says nothing about whether the output is indigenous or competitively priced.']::text[],ARRAY['pib-defprod-fy25']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('defence-export-private-share','Private sector share of defence exports','Share of defence export value originating from private firms rather than DPSUs.','defence','% of export value','%','fiscal-year',NULL,'official','high','2026-08-17',ARRAY['Much of the private share is components and sub-assemblies feeding foreign primes, not finished platforms sold under an Indian badge.']::text[],ARRAY['pib-defexp-fy25','pib-defexp-fy24']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('defence-export-authorisations','Defence export authorisations issued','Count of export authorisations issued by the Department of Defence Production in a fiscal year.','defence','authorisations','count','fiscal-year',true,'official','high','2026-08-17',ARRAY['An authorisation is a permission to export, not a completed sale. Counts breadth of exporter participation rather than value.']::text[],ARRAY['pib-defexp-fy25']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('defence-budget','Ministry of Defence budget allocation','Total Union Budget allocation to the Ministry of Defence, including defence pensions and civil expenditure.','defence','₹ crore (nominal)','₹ cr','fiscal-year',NULL,'official','high','2026-08-17',ARRAY['Includes pensions, which are roughly a fifth of the total and buy no new capability. Comparisons with China''s or America''s budgets that ignore this overstate India''s usable defence spend.','Nominal rupees. Real growth after inflation is far shallower than the headline curve.']::text[],ARRAY['pib-defbudget-fy26','prs-dfg-defence-2026','theprint-defbudget-history']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('defence-capital-outlay','Defence capital outlay','Budget line for capital acquisition and infrastructure — the portion that buys new equipment rather than paying salaries and pensions.','defence','₹ crore (nominal)','₹ cr','fiscal-year',true,'official','high','2026-08-17',ARRAY['This is the single most informative defence budget line: it is what actually modernises the force.','Capital outlay has hovered near 26-27% of the defence budget for a decade. That ratio, not the headline total, is the constraint.','Capital outlay for FY2025-26 was reported as fully utilised at about ₹1.86 lakh crore against the ₹1.80 lakh crore budget estimate shown here.']::text[],ARRAY['pib-defbudget-fy26','newsonair-capoutlay-fy26']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('nuclear-warheads','Estimated nuclear warhead inventory','Independent expert estimate of India''s total nuclear warhead stockpile as of January each year.','defence','warheads (estimated)','warheads','point-in-time',NULL,'think-tank','low','2026-08-17',ARRAY['India publishes nothing about its arsenal. Every figure here is an external estimate inferred from fissile-material production and delivery systems, with an error bar SIPRI itself describes as significant.','Treat this series as an order-of-magnitude indicator only. It is the least certain dataset on this site and is marked low confidence for that reason.']::text[],ARRAY['sipri-yb25-nuclear']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('arms-imports-global-share','India''s share of global major-arms imports','India''s share of world imports of major conventional weapons, measured by SIPRI trend-indicator value over rolling five-year windows.','defence','% of global imports','%','annual',false,'think-tank','medium','2026-08-17',ARRAY['SIPRI''s trend-indicator value measures military capability transferred, not money paid. It is not comparable to customs data.','A falling share is usually read as rising self-reliance. It can equally reflect delayed procurement — India''s import decline coincided with well-documented acquisition delays.']::text[],ARRAY['sipri-at-2024','theprint-sipri-imports']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('arms-imports-russia-share','Russia''s share of India''s arms imports','Share of India''s major-arms imports supplied by Russia, over rolling five-year windows.','defence','% of India''s imports','%','annual',NULL,'think-tank','medium','2026-08-17',ARRAY['The halving of Russian dependence since 2010-14 is one of the clearest structural shifts in Indian defence procurement.','Legacy Russian platforms still dominate the in-service fleet; supplier diversification shows up in new orders long before it shows up in the order of battle.']::text[],ARRAY['sipri-at-2024','theprint-sipri-imports']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('defence-corridor-committed','Defence corridor investment committed','Investment committed via MoU to each defence industrial corridor.','defence','₹ crore','₹ cr','point-in-time',true,'press','low','2026-08-17',ARRAY['Committed is not grounded. Against roughly ₹70,000 crore of commitments across both corridors, grounded investment is about ₹10,855 crore — around 15%.','Marked low confidence: figures come from ministry statements at differing dates with no single reconciled public register.']::text[],ARRAY['indianmasterminds-corridors-70k','swarajya-defcorridor-investment']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('defence-corridor-grounded','Defence corridor investment grounded','Investment actually deployed on the ground in each defence industrial corridor.','defence','₹ crore','₹ cr','point-in-time',true,'press','low','2026-08-17',ARRAY['This is the number that matters, and the one rarely quoted. Grounded investment runs at roughly 15% of committed.','Marked low confidence: no independently audited register of grounded corridor investment was located.']::text[],ARRAY['indianmasterminds-corridors-70k','swarajya-defcorridor-investment']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('defence-corridors-count','Defence industrial corridors by status','Count of announced defence industrial corridors by delivery status.','defence','corridors','count','point-in-time',true,'press','low','2026-08-17',ARRAY['Two corridors (UP, Tamil Nadu) are operating with land allotted and units producing. Two more (Maharashtra, Assam) are announced but not established.','Graded low confidence: the operational/announced split rests on ministry statements relayed by press, with no single reconciled public register.']::text[],ARRAY['indianmasterminds-corridors-70k','swarajya-defcorridor-investment']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('defence-corridor-nodes','Defence corridor nodes','Count of designated nodal industrial locations within each established defence corridor.','defence','nodes','count','point-in-time',NULL,'official','low','2026-08-17',ARRAY['Node lists are press-sourced. They are stable and uncontested, but no primary notification was located during verification, so this is graded low rather than treated as a record.']::text[],ARRAY['swarajya-defcorridor-investment']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('defence-corridor-jobs','Direct jobs created in UP defence corridor','Direct employment reported at units established in the Uttar Pradesh defence industrial corridor.','defence','jobs','jobs','point-in-time',true,'press','low','2026-08-17',ARRAY['Reported against a stated potential of 50,000 jobs — actual delivery is around a quarter of that.','No independent audit of these employment numbers was located.']::text[],ARRAY['indianmasterminds-corridors-70k']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('defence-corridor-mous','MoUs signed in UP defence corridor','Count of memoranda of understanding signed with the Uttar Pradesh defence industrial corridor authority, and land allotments made.','defence','count','count','point-in-time',NULL,'press','low','2026-08-17',ARRAY['170 MoUs converted into 57 land allotments — a conversion rate of roughly one in three. Useful as a reality check on announcement-driven reporting.']::text[],ARRAY['indianmasterminds-corridors-70k']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('defence-export-destinations','Countries receiving Indian defence exports','Approximate count of destination countries for Indian defence exports in a fiscal year.','defence','countries','countries','fiscal-year',true,'official','medium','2026-08-17',ARRAY['Reported as ''around 80 countries''. Breadth includes small consignments of parts and ammunition, so country count overstates strategic reach.']::text[],ARRAY['pib-defexp-fy25']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('nh-network-length','National highway network length','Total length of roads designated as National Highways by the Ministry of Road Transport & Highways.','infrastructure','kilometres','km','fiscal-year',true,'official','high','2026-08-17',ARRAY['Network length grows partly by building new roads and partly by re-designating existing state highways as national highways. The two are not distinguished in the headline figure, so this series overstates new construction.','Use ''National highways constructed per year'' alongside this for the build-rate picture.']::text[],ARRAY['pib-morth-yer-2025','ddnews-nh-growth','swarajya-nh-fy25']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('nh-constructed-annual','National highways constructed per year','Kilometres of national highway completed during the fiscal year.','infrastructure','kilometres per year','km/yr','fiscal-year',true,'official','high','2026-08-17',ARRAY['The honest read: construction peaked at 13,327 km in FY2020-21 and has since plateaued around 10,000-12,000 km a year. The ''record pace'' framing does not survive contact with this series.','FY2020-21''s peak coincided with pandemic-period low traffic, which eased construction windows.']::text[],ARRAY['pib-morth-yer-2025','pib-morth-yer-2024','deccan-nh-construction']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('expressway-length','Access-controlled high-speed corridors and expressways','Length of access-controlled national high-speed corridors and expressways — the grade-separated, limited-access subset of the network.','infrastructure','kilometres','km','point-in-time',true,'official','high','2026-08-17',ARRAY['This is the most genuinely impressive infrastructure series on the site: a 55-fold increase off a near-zero base in a decade.','Still small in absolute terms — China''s expressway network is roughly thirty times longer.']::text[],ARRAY['pib-morth-yer-2025']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('nh-four-lane-plus','Four-lane and above national highways','Length of national highway with four or more lanes.','infrastructure','kilometres','km','point-in-time',true,'official','high','2026-08-17',ARRAY['Lane-width upgrades matter more for freight throughput than raw network length. This series has grown faster than total network length, which is the right direction.']::text[],ARRAY['pib-morth-yer-2025']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('airports-operational','Operational airports','Count of airports and airstrips in India handling scheduled commercial passenger flights.','infrastructure','airports','airports','point-in-time',true,'official','medium','2026-08-17',ARRAY['Counts drift between releases (157, 159, 160, 163) because ''operational'' sometimes includes heliports, water aerodromes and seasonally-served strips. Treat the trend as solid and any single year as ±5.','Several UDAN airports have since lost their scheduled service. An airport being built is not the same as an airport being used — see the route-viability caveats on the methodology page.']::text[],ARRAY['newsonair-airports-160','newsonair-airports-157','moca-rs-1870']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('airports-by-type','Airports by classification','Breakdown of operational airports by customs and international designation.','infrastructure','airports','airports','point-in-time',NULL,'official','medium','2026-08-17','{}'::text[],ARRAY['moca-rs-1870']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('udan-aerodromes','Aerodromes operationalised under UDAN','Count of airports, heliports and water aerodromes brought into scheduled service under the UDAN regional connectivity scheme since 2016.','infrastructure','aerodromes','count','point-in-time',true,'official','high','2026-08-17','{}'::text[],ARRAY['newsonair-airports-160']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('udan-routes','UDAN routes inaugurated','Cumulative count of regional air routes started under the UDAN scheme.','infrastructure','routes','routes','point-in-time',true,'official','medium','2026-08-17',ARRAY['Cumulative inaugurations, not currently-flying routes. A material share of UDAN routes have been discontinued after their three-year viability-gap subsidy expired — the scheme''s central unresolved weakness.']::text[],ARRAY['newsonair-airports-160']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('metro-network-length','Operational metro rail network','Total length of metro rail in revenue service across Indian cities.','infrastructure','kilometres','km','point-in-time',true,'official','high','2026-08-17',ARRAY['India passed 1,000 km in October 2025 to become the third-largest metro network in the world, behind China and the United States.','Ridership has not kept pace with track: several networks run far below the projections used to justify them. Length is an input, not an outcome.']::text[],ARRAY['pib-metro-2025','metrorailtoday-3rd-largest']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('metro-cities','Cities with operational metro rail','Count of Indian cities with a metro system in revenue service.','infrastructure','cities','cities','point-in-time',true,'official','high','2026-08-17','{}'::text[],ARRAY['pib-metro-2025']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('metro-ridership','Daily metro rail ridership','Average daily passenger journeys across all operational Indian metro systems.','infrastructure','million journeys per day','m/day','point-in-time',true,'official','medium','2026-08-17',ARRAY['Ridership grew 4x while network length grew 4.1x — meaning average passengers per kilometre has been flat. New lines are not, on average, as well used as the old ones.']::text[],ARRAY['pib-metro-2025']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('major-ports-cargo','Cargo handled at major ports','Total cargo throughput at India''s centrally-administered major ports in a fiscal year.','infrastructure','million tonnes','MT','fiscal-year',true,'official','high','2026-08-17','{}'::text[],ARRAY['pib-ports-fy26','newsonair-ports-fy25']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('all-ports-cargo','Cargo handled at all ports','Total cargo throughput across both major and non-major (state) ports.','infrastructure','million tonnes','MT','fiscal-year',true,'official','medium','2026-08-17',ARRAY['Non-major ports have grown faster than major ports over the period, driven largely by private terminals on the west coast.']::text[],ARRAY['pib-ports-fy26']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('port-capacity','Total port capacity','Installed annual cargo handling capacity across major and non-major ports.','infrastructure','million tonnes per annum','MTPA','fiscal-year',true,'official','medium','2026-08-17',ARRAY['Capacity (2,817 MTPA) runs well ahead of throughput (1,668 MT) — utilisation near 59%. Headroom is healthy; it also means further capacity spending has weak near-term returns.']::text[],ARRAY['pib-ports-fy26']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('port-turnaround-time','Average vessel turnaround time at major ports','Mean time a vessel spends in port from arrival to departure.','infrastructure','hours','hrs','fiscal-year',false,'official','medium','2026-08-17',ARRAY['Genuine operational gain, and one of the few Indian logistics metrics that now beats several developed-economy averages.','Turnaround improvement has stalled since FY2021-22 — from 52.87 to 48.84 hours in four years, against a halving in the decade before.']::text[],ARRAY['constructionmirror-tat-fy26','pib-ports-fy26']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('total-exports','Total exports (goods + services)','Combined merchandise and services exports for the fiscal year, as reported by the Department of Commerce.','trade','US$ billion','$bn','fiscal-year',true,'official','high','2026-08-17',ARRAY['FY2024-25 was first reported at $820.93 bn and later revised to $825.26 bn as late services returns came in. Services export data is estimated monthly and revised for up to a year.','Growth is now almost entirely services-led. Merchandise exports grew 0.93% in FY2025-26 against 8.71% for services.']::text[],ARRAY['newsonair-exports-fy26','newsonair-exports-fy25','pib-commerce-yer-2025']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('merchandise-exports','Merchandise exports','Value of physical goods exported during the fiscal year.','trade','US$ billion','$bn','fiscal-year',true,'official','high','2026-08-17',ARRAY['Effectively flat in FY2025-26. This is the clearest single sign that ''Make in India'' has not yet converted into export competitiveness in goods.','Petroleum products remain a large share, which makes the headline sensitive to crude prices rather than manufacturing capability.']::text[],ARRAY['bw-exports-fy26','pib-commerce-yer-2025']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('services-exports','Services exports','Value of services exported during the fiscal year, including software, business and financial services.','trade','US$ billion','$bn','fiscal-year',true,'official','high','2026-08-17',ARRAY['India''s genuine global strength. Telecom/computer/information services alone were $206.6 bn — about 49% of services exports.','Concentration is also the risk: roughly half of services exports sit in one sector exposed to AI-driven automation of exactly that work.']::text[],ARRAY['bw-exports-fy26','pib-commerce-yer-2025']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('services-exports-composition','Services exports by segment','Breakdown of services export value by major category, FY2025-26.','trade','US$ billion','$bn','point-in-time',NULL,'official','high','2026-08-17','{}'::text[],ARRAY['pib-commerce-yer-2025','bw-exports-fy26']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('gdp-nominal-usd','GDP, nominal','Gross domestic product at current market prices in US dollars.','economy','US$ trillion','$tn','annual',true,'multilateral','medium','2026-08-17',ARRAY['India is the 5th largest economy by nominal GDP as of 2025, behind the US, China, Germany and Japan — not 4th, a claim that circulates widely but did not hold at the time of verification.','Nominal dollar GDP moves with the exchange rate. Rupee depreciation has repeatedly masked real growth in this series.','Per-capita GDP, not total GDP, is the meaningful development measure — see the benchmark page.']::text[],ARRAY['worldbank-wdi']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('isro-missions-cumulative','ISRO launch missions, cumulative','Cumulative count of ISRO launch vehicle missions flown since the SLV programme began in 1979.','space','missions','missions','point-in-time',true,'press','medium','2026-08-17',ARRAY['The 100th mission was reached in January 2025, 46 years after the first launch.','Cadence, not total, is the real story: 43 missions in the 35 years to 2009, then 91 missions in the 17 years to 2026.']::text[],ARRAY['thefederal-isro-100','factly-pslv']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('isro-launch-cadence','ISRO launch cadence by era','Average launch missions per year across two distinct eras of the Indian space programme.','space','missions per year','/yr','point-in-time',true,'press','medium','2026-08-17',ARRAY['A roughly 4x increase in launch tempo. Still an order of magnitude below China (60+ orbital launches a year) and SpaceX alone.']::text[],ARRAY['factly-pslv']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('isro-launches-by-vehicle','ISRO missions by launch vehicle','Count of missions flown by each Indian launch vehicle family.','space','missions','missions','point-in-time',NULL,'press','medium','2026-08-17',ARRAY['PSLV has carried roughly every second ISRO satellite. That dependence is a single-point risk, underlined by third-stage failures on PSLV-C61 (May 2025) and PSLV-C62 (January 2026).']::text[],ARRAY['thefederal-isro-100','factly-pslv']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('isro-record-single-launch','Satellites on a single launch','Largest number of satellites placed in orbit by India on one launch vehicle.','space','satellites','sats','point-in-time',true,'press','high','2026-08-17',ARRAY['The 2017 PSLV-C37 record of 104 satellites stood as a world record until surpassed by SpaceX Transporter missions.']::text[],ARRAY['factly-pslv']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('wdi-gdp-current-usd','GDP (current US$)','Gross domestic product at current market prices.','economy','current US$','US$','annual',true,'multilateral','high','2026-08-19',ARRAY['World Bank indicator NY.GDP.MKTP.CD. History is restated by the World Bank as national accounts are revised; this series is rewritten in full on every pipeline run rather than appended to.']::text[],ARRAY['worldbank-wdi']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
INSERT INTO bharat_tracker.series (id,title,definition,category,unit,unit_short,frequency,higher_is_better,provenance,confidence,last_verified,notes,source_ids,updated_at) VALUES ('wdi-gdp-growth','GDP growth','Annual percentage growth of GDP at constant local prices.','economy','% per year','%','annual',true,'multilateral','high','2026-08-19',ARRAY['World Bank indicator NY.GDP.MKTP.KD.ZG. History is restated by the World Bank as national accounts are revised; this series is rewritten in full on every pipeline run rather than appended to.']::text[],ARRAY['worldbank-wdi']::text[],now()) ON CONFLICT (id) DO UPDATE SET title=EXCLUDED.title,definition=EXCLUDED.definition,category=EXCLUDED.category,unit=EXCLUDED.unit,unit_short=EXCLUDED.unit_short,frequency=EXCLUDED.frequency,higher_is_better=EXCLUDED.higher_is_better,provenance=EXCLUDED.provenance,confidence=EXCLUDED.confidence,last_verified=EXCLUDED.last_verified,notes=EXCLUDED.notes,source_ids=EXCLUDED.source_ids,updated_at=now();
